# ============================================================
# Bloggie App - API Architecture Setup
# Expo + React Native + Laravel API
# ============================================================

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "==============================================" -ForegroundColor Cyan
Write-Host " Bloggie App API Architecture Setup" -ForegroundColor Cyan
Write-Host "==============================================" -ForegroundColor Cyan
Write-Host ""

Write-Host "[1/4] Installing API dependencies..." -ForegroundColor Yellow
npm install axios @tanstack/react-query @react-native-async-storage/async-storage
Write-Host "Dependencies installed." -ForegroundColor Green
Write-Host ""

Write-Host "[2/4] Creating project directories..." -ForegroundColor Yellow

$directories = @(
    "src/constants",
    "src/context",
    "src/hooks",
    "src/lib",
    "src/services",
    "src/utils"
)

foreach ($directory in $directories) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
    Write-Host "Ready: $directory" -ForegroundColor Green
}

Write-Host ""
Write-Host "[3/4] Creating API architecture files..." -ForegroundColor Yellow

$files = @{
    "src/constants/theme.js" = ""
    "src/lib/storage.js" = ""
    "src/lib/api.js" = ""
    "src/lib/queryClient.js" = ""
    "src/services/authService.js" = ""
    "src/services/postService.js" = ""
    "src/services/userService.js" = ""
    "src/services/bookmarkService.js" = ""
    "src/hooks/useAuth.js" = ""
    "src/hooks/usePosts.js" = ""
    "src/hooks/useProfile.js" = ""
    "src/hooks/useBookmarks.js" = ""
    "src/utils/formatDate.js" = ""
    "src/utils/helpers.js" = ""
    "src/context/AuthContext.jsx" = ""
    ".env" = "IyBBbmRyb2lkIEVtdWxhdG9yIC0+IFdpbmRvd3MgaG9zdCBtYWNoaW5lCkVYUE9fUFVCTElDX0FQSV9VUkw9aHR0cDovLzEwLjAuMi4yOjgwMDAvYXBpL3YxCgojIEZvciBhIHBoeXNpY2FsIEFuZHJvaWQgZGV2aWNlLCByZXBsYWNlIHRoZSBVUkwgYWJvdmUgd2l0aDoKIyBFWFBPX1BVQkxJQ19BUElfVVJMPWh0dHA6Ly9ZT1VSX1BDX0xBTl9JUDo4MDAwL2FwaS92MQo="
}

foreach ($file in $files.Keys) {
    $directory = Split-Path $file -Parent

    if ($directory -and -not (Test-Path $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }

    $bytes = [System.Convert]::FromBase64String($files[$file])
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)

    if (Test-Path $file) {
        Write-Host "Skipped existing file: $file" -ForegroundColor DarkGray
    }
    else {
        [System.IO.File]::WriteAllText(
            (Join-Path (Get-Location) $file),
            $content,
            (New-Object System.Text.UTF8Encoding($false))
        )

        Write-Host "Created: $file" -ForegroundColor Green
    }
}

Write-Host ""
Write-Host "[4/4] Setup complete." -ForegroundColor Yellow
Write-Host ""
Write-Host "API URL:" -ForegroundColor Cyan
Write-Host "http://10.0.2.2:8000/api/v1" -ForegroundColor White
Write-Host ""
Write-Host "Architecture:" -ForegroundColor Cyan
Write-Host "src/constants/theme.js"
Write-Host "src/context/AuthContext.jsx"
Write-Host "src/hooks/*"
Write-Host "src/lib/*"
Write-Host "src/services/*"
Write-Host "src/utils/*"
Write-Host ""
Write-Host "Restart Expo:" -ForegroundColor Yellow
Write-Host "npx expo start -c" -ForegroundColor White
Write-Host ""
